import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		var inner sync.WaitGroup
		inner.Add(1)
		go func() {
			defer inner.Done()
			fmt.Println(4)
		}()
		inner.Wait()
		fmt.Println(5)
	}()
	wg.Wait()
}

